local function stageInput(t) for _, s in ipairs(seq) do if t >= s[1] and t < s[2] then return s[3] end end return {} end
local function menuInput(f)
  local m = f % 160
  if m < 20 then return {start = true} elseif m < 60 then return {} elseif m < 80 then return {a = true}
  elseif m < 100 then return {} elseif m < 110 then return {right = true} elseif m < 130 then return {}
  elseif m < 140 then return {down = true} else return {} end
end
local fieldAddrs = {0x300,0x348,0x330,0x318,0x390,0x378,0x360,0x3A8,0x3C0,0x3D8,0x3F0,0x408,0x420,0x438,0x450,0x468,0x480,0x498,0x4B0,0x4C8,0x4E0,0x4F8,0x510,0x528,0x540,0x558,0x570,0x588,0x5A0,0x5B8}
local function logRows(T)
  if T == -1 then
    -- initial state of every slot, live or not: dead slots keep stale bytes that new objects inherit
    local all = {}
    for x = 1, 23 do
      local o = { string.format("%02X", x) }
      for _, a in ipairs(fieldAddrs) do o[#o + 1] = string.format("%02X", rd(a + x)) end
      all[#all + 1] = table.concat(o, " ")
    end
    oout:write("S " .. table.concat(all, " ") .. "\n")
  end
  out:write(string.format("%d %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X\n", T,
        capP, capH, rd(0x30), rd(0x31), rd(0x348), rd(0x330), rd(0x318), rd(0x390), rd(0x378), rd(0x360),
        rd(0x3F0), rd(0x3D8), rd(0xB0), rd(0x300), rd(0xF9), rd(0xFC), rd(0x558), rd(0x540), rd(0x528), rd(0x3C)))
  local parts = { string.format("%d G %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X", T, rd(0xE4), rd(0xE6), rd(0xE5), rd(0x95), rd(0x9E), rd(0x9F), rd(0x2F), rd(0xFD), rd(0x2E), rd(0xE7), rd(0x92)) }
  local n = 0
  local objs = {}
  for x = 1, 23 do
    if rd(0x300 + x) ~= 0 then
      n = n + 1
      local o = { string.format("%02X", x) }
      for _, a in ipairs({0x300,0x348,0x330,0x318,0x390,0x378,0x360,0x3A8,0x3C0,0x3D8,0x3F0,0x408,0x420,0x438,0x450,0x468,0x480,0x498,0x4B0,0x4C8,0x4E0,0x4F8,0x510,0x528,0x540,0x558,0x570,0x588,0x5A0,0x5B8}) do o[#o + 1] = string.format("%02X", rd(a + x)) end
      objs[#objs + 1] = table.concat(o, " ")
    end
  end
  oout:write(table.concat(parts, " ") .. " O " .. n .. " " .. table.concat(objs, " ") .. "\n")
  local oam = {}
  for a = 0x200, 0x2FF do oam[#oam + 1] = string.format("%02X", rd(a)) end
  aout:write(T .. " " .. table.concat(oam) .. "\n")

  do local r = {} for _, a in ipairs({0x1B,0x1C,0xF0,0xF1,0xFA,0xFD,0x13E,0x13F,0x43,0x44,0xEF}) do r[#r + 1] = string.format("%02X", rd(a)) end aux:write(T .. " " .. table.concat(r, " ") .. "\n") end
end
