-- end of one logic frame: the instruction after the object draw pass (code_3EC7C6)
emu.addMemoryCallback(function()
  if stageFrame and frame - stageFrame >= WAIT - 1 then
    if nlog < FRAMES then
      logRows(nlog)
      nlog = nlog + 1
    end
  end
end, emu.callbackType.exec, 0xC7C6)

