  end

  frame = frame + 1
end, emu.eventType.endFrame)
emu.addEventCallback(function()
  if false then emu.setInput(selInput(frame - selStart), 0)
  elseif false then emu.setInput((frame % 40 < 4) and {start = true} or {}, 0)
  elseif stageFrame and frame - stageFrame >= WAIT then emu.setInput(stageInput(frame - stageFrame - WAIT), 0)
  elseif stageFrame then emu.setInput({}, 0) else emu.setInput(menuInput(frame), 0) end
end, emu.eventType.inputPolled)

local dl = io.open("C:/Users/joele/Desktop/MegaMan4 Project/harness/dbg_log.txt", "w")
emu.addMemoryCallback(function(addr, val)
  if nlog >= 0 and nlog <= 5 then
    local st = emu.getState()
    dl:write(string.format("T=%d write %04X <- %02X pc=%04X a=%02X x=%02X y=%02X\n", nlog, addr, val, st["cpu.pc"], st["cpu.a"], st["cpu.x"], st["cpu.y"]))
    dl:flush()
  end
end, emu.callbackType.write, 0x330, 0x330)
